// B"H
/**
 * Worker Builder
 * The engine worker used to be assembled at runtime into a blob: URL, but the
 * site CSP blocks blob: workers (worker-src falls back to script-src 'self',
 * no blob:), so `new Worker(blobUrl)` threw and the inspector could never
 * load a model. The same code now ships as the static same-origin file
 * worker-bundle.js (generated by build-worker-bundle.mjs from worker_src/*).
 * No CSP change needed. Re-run `node build-worker-bundle.mjs` after editing
 * worker_src/*.
 */
export function createWorker() {
    return new Worker(new URL('./worker-bundle.js', import.meta.url));
}
